if len(word) <= 1:
    return word

# Check if word is all uppercase or all lowercase
if word.isupper() or word.islower():
    return word

# For mixed case words, check the first two characters
if len(word) >= 2:
    first_char = word[0]
    second_char = word[1]

    # Both first two chars are lowercase - convert all to lowercase
    if first_char.islower() and second_char.islower():
        return word.lower()

    # Both first two chars are uppercase - likely an acronym, keep as is
    elif first_char.isupper() and second_char.isupper():
        return word

    # First uppercase, second lowercase - capitalize (first upper, rest lower)
    elif first_char.isupper() and second_char.islower():
        return word[0] + word[1:].lower()

    # First lowercase, second uppercase - unusual pattern, convert to lowercase
    else:
        return word.lower()

# Fallback case
return word

