import numpy as np

# Handle edge cases
if np.isscalar(x):
    if x < -1.0:
        return np.nan
    elif x == -1.0:
        return -np.inf
    else:
        return np.log1p(x)
else:
    # For array-like inputs, handle element-wise
    result = np.log1p(x)
    # Replace values where x < -1 with NaN
    if hasattr(result, 'shape'):
        mask = x < -1.0
        if np.any(mask):
            result = result.copy()
            result[mask] = np.nan
    return result
